(function () {
                    function growifyGetCookie(growifyName) {
                        var growifyNameEQ = growifyName + "=";
                        var growifyCa = document.cookie.split(';');
                        for (var i = 0; i < growifyCa.length; i++) {
                            var growifyC = growifyCa[i];
                            while (growifyC.charAt(0) == ' ') growifyC = growifyC.substring(1, growifyC.length);
                            if (growifyC.indexOf(growifyNameEQ) == 0) return decodeURIComponent(growifyC.substring(growifyNameEQ.length, growifyC.length));
                        }
                        return null;
                    }
                    function growifyEraseCookie(growifyName) {
                        document.cookie = growifyName + '=; Max-Age=-99999999; path=/;';
                    }
                    function checkGrowifyLead() {
                        var growifyLeadData = growifyGetCookie('growify_lead_tracking');
                        if (growifyLeadData) {
                            try {
                                var growifyBinaryString = atob(growifyLeadData);
                                var growifyBytes = new Uint8Array(growifyBinaryString.length);
                                for (var i = 0; i < growifyBinaryString.length; i++) {
                                    growifyBytes[i] = growifyBinaryString.charCodeAt(i);
                                }
                                var growifyDecodedString = new TextDecoder().decode(growifyBytes);
                                var growifyDecoded = JSON.parse(growifyDecodedString);

                                window.grpQueue = window.grpQueue || [];
                                if (!window.grp) { window.grp = function () { window.grpQueue.push(arguments); }; }
                                window.grp('lead-generated', growifyDecoded);

                                // Meta Lead Event
                                if (typeof fbq !== 'undefined' && false) {
                                    fbq('track', 'Lead', {
                                        content_name: growifyDecoded.formName,
                                        content_category: growifyDecoded.source
                                    }, {
                                        eventID: 'orderid_' + growifyDecoded.orderId
                                    });
                                }

                                growifyEraseCookie('growify_lead_tracking');
                            } catch (e) { console.error('Growify: Error parsing lead data', e); }
                        }
                    }
                    checkGrowifyLead();
                    setInterval(checkGrowifyLead, 1000);
                })();

//# sourceURL=growify-pixel-js-after

