(function () {


  // ---------------------------
  // 0) SAFE TRACK WRAPPER
  // ---------------------------
  function track(name, props) {
    try {
      if (typeof pa !== 'undefined' && pa && typeof pa.track === 'function') {
        pa.track(Object.assign({ name }, props || {}));
      }
    } catch (e) {}
  }

  // Dedupe helper (żeby nie wysyłać 10x tego samego)
  const fired = new Set();
  function trackOnce(key, name, props) {
    if (fired.has(key)) return;
    fired.add(key);
    track(name, props);
  }

  // Odpala event tylko raz na sesję (refresh nie nabija)
  function fireOncePerSession(key, fn) {
    try {
      const k = 'pa_' + key;
      if (sessionStorage.getItem(k)) return;
      sessionStorage.setItem(k, '1');
      fn();
    } catch (e) {
      fn();
    }
  }

  // ---------------------------
  // 1) CLICK TRACKING: tel/mail/whatsapp
  // ---------------------------
  document.addEventListener(
    'click',
    function (e) {
      const a = e.target.closest('a');
      if (!a) return;

      const href = (a.getAttribute('href') || '').trim();
      if (!href) return;

      if (href.startsWith('tel:')) track('Intent – Click Phone', { href });
      if (href.startsWith('mailto:')) track('Intent – Click Email', { href });
      if (href.includes('wa.me') || href.includes('whatsapp')) track('Intent – Click WhatsApp', { href });
    },
    true
  );

  // ---------------------------
  // 1b) External shop click: hi-design.bluecollection.gifts (menu button)
  // ---------------------------
  document.addEventListener(
    'click',
    function (e) {
      const a = e.target.closest('a');
      if (!a) return;

      const href = (a.getAttribute('href') || '').trim();
      if (!href || !href.includes('hi-design.bluecollection.gifts')) return;

      const inHeader = !!a.closest('#header, .ct-header, header');

      track(
        inHeader ? 'Intent – Gadżety – External Shop Click (Header)' : 'Intent – Gadżety – External Shop Click',
        { href }
      );
    },
    true
  );

  // ---------------------------
  // 2) CUSTOM CTA TRACKING via data-pa
  // ---------------------------
  // Dodajesz na przycisk/link/kafel:
  // data-pa="Intent – Strony WWW – CTA Click"
  // opcjonalnie: data-pa-extra="coś"
  document.addEventListener(
    'click',
    function (e) {
      const el = e.target.closest('[data-pa]');
      if (!el) return;

      const name = el.getAttribute('data-pa');
      if (!name) return;

      const extra = el.getAttribute('data-pa-extra');
      const href = el.getAttribute('href') || undefined;

      track(name, Object.assign({}, extra ? { extra } : null, href ? { href } : null));
    },
    true
  );

  // ---------------------------
  // 3) SCROLL 50% / 75%
  // ---------------------------
  let fired50 = false;
  let fired75 = false;

  function calcScrollPct() {
    const doc = document.documentElement;
    const scrollTop = doc.scrollTop || document.body.scrollTop || 0;
    const scrollHeight = doc.scrollHeight || document.body.scrollHeight || 0;
    const clientHeight = doc.clientHeight || window.innerHeight || 0;
    const maxScroll = scrollHeight - clientHeight;
    if (maxScroll <= 0) return 0;
    return Math.round((scrollTop / maxScroll) * 100);
  }

  let scrollT = null;
  function onScrollThrottled() {
    if (scrollT) return;
    scrollT = setTimeout(function () {
      scrollT = null;

      const pct = calcScrollPct();

      if (!fired50 && pct >= 50) {
        fired50 = true;
        track('Awareness – Scroll 50');
      }
      if (!fired75 && pct >= 75) {
        fired75 = true;
        track('Awareness – Scroll 75');
      }

      if (fired50 && fired75) window.removeEventListener('scroll', onScrollThrottled);
    }, 400);
  }
  window.addEventListener('scroll', onScrollThrottled, { passive: true });

  // ---------------------------
  // 4) TIME ON PAGE 60s / 120s / 180s (only if Scroll 50 happened)
  // ---------------------------
  setTimeout(() => trackOnce('time60', 'Awareness – Time 60s'), 60000);
  setTimeout(() => trackOnce('time120', 'Awareness – Time 120s'), 120000);
  setTimeout(() => {
    if (fired50) trackOnce('time180_scroll50', 'Awareness – Time 180s (after Scroll 50)');
  }, 180000);

  // ---------------------------
  // 5) CF7 SUCCESS (hard conversion)
  // ---------------------------
  document.addEventListener(
    'wpcf7mailsent',
    function (e) {
      const formId = e?.detail?.contactFormId || 'unknown';
      track('Conversion – Form Sent (CF7)', { formId });
    },
    false
  );

  // ---------------------------
  // 6) VBOUT TRACKING (Open + Submit Attempt)
  // ---------------------------
  function isVboutContainer(node) {
    if (!node || node.nodeType !== 1) return false;
    if (node.classList && node.classList.contains('vboutEmbedFormBox')) return true;
    const id = node.getAttribute && node.getAttribute('id');
    if (id && /vboutEmbedFormBox-|vbtEFWrapper-/.test(id)) return true;
    return false;
  }

  function findVboutContainers() {
    return Array.from(
      document.querySelectorAll('.vboutEmbedFormBox, [id^="vboutEmbedFormBox-"], [id^="vbtEFWrapper-"]')
    );
  }

  function bindVbout(container) {
    if (!container || container.__paBound) return;
    container.__paBound = true;

    const formKey = container.getAttribute('data-vbtfc') || container.id || 'vbout';
    track('Intent – Form Open (VBOUT)', { formKey });

    function bindInnerForm() {
      const form = container.querySelector('form');
      if (form && !form.__paBound) {
        form.__paBound = true;
        form.addEventListener(
          'submit',
          function () {
            track('Intent – Form Submit Attempt (VBOUT)', { formKey });
          },
          true
        );
      }

      const submitBtn = container.querySelector('button[type="submit"], input[type="submit"]');
      if (submitBtn && !submitBtn.__paBound) {
        submitBtn.__paBound = true;
        submitBtn.addEventListener(
          'click',
          function () {
            track('Intent – Form Submit Attempt (VBOUT)', { formKey });
          },
          true
        );
      }
    }

    bindInnerForm();

    const innerObserver = new MutationObserver(function () {
      bindInnerForm();
      // UWAGA: NIE wysyłamy tu "Sent" po tekście.
      // VBOUT konwersję robimy twardo na stronie podziękowania (#7).
    });

    innerObserver.observe(container, { childList: true, subtree: true });
  }

  findVboutContainers().forEach(bindVbout);

  const docObserver = new MutationObserver(function (mutations) {
    for (const m of mutations) {
      for (const node of m.addedNodes || []) {
        if (isVboutContainer(node)) bindVbout(node);

        if (node && node.nodeType === 1) {
          const nested = node.querySelectorAll
            ? node.querySelectorAll('.vboutEmbedFormBox, [id^="vboutEmbedFormBox-"], [id^="vbtEFWrapper-"]')
            : [];
          if (nested && nested.length) nested.forEach(bindVbout);
        }
      }
    }
  });
  docObserver.observe(document.documentElement, { childList: true, subtree: true });

  // ---------------------------
  // 7) VBOUT HARD CONVERSION (thank-you page)
  // URL: https://hi-design.pl/podziekowanie-za-zapis-do-listy/
  // ---------------------------
  (function () {
    const currentUrl = window.location.href;

    if (currentUrl.includes('/podziekowanie-za-zapis-do-listy/')) {
      fireOncePerSession('vbout_thankyou_conversion', function () {
        track('Conversion – Form Sent (VBOUT)', { source: 'thankyou_page' });
      });
    }
  })();

  // ---------------------------
  // 8) FUNNEL: Cart / Checkout / Purchase (WooCommerce)
  // koszyk: /koszyk/
  // checkout: /zamowienie/
  // thank-you: URL zawiera "order-received"
  // ---------------------------
  (function () {
    const path = window.location.pathname || '';
    const href = window.location.href || '';

    if (path === '/koszyk/' || path.startsWith('/koszyk/')) {
      fireOncePerSession('cart_view', function () {
        track('Intent – Cart View', { path });
      });
    }

    if (path === '/zamowienie/' || path.startsWith('/zamowienie/')) {
      fireOncePerSession('checkout_start', function () {
        track('Intent – Checkout Start', { path });
      });
    }

    if (href.includes('order-received')) {
      fireOncePerSession('purchase_completed', function () {
        track('Conversion – Purchase Completed', { path });
      });
    }
  })();
})();

(function () {

    const EXTRA_GAP = 32;      // ile px nad Smart Barem
    const SHIFT_RIGHT = 18;    // ile px w prawo

    function moveCharla() {

        const bar = document.querySelector('.hdsb-bar');
        const charla = document.querySelector('charla-widget');

        if (!bar || !charla) return;

        const charlaIcon = charla.querySelector('charla-icon');

        if (!charlaIcon || !charlaIcon.shadowRoot) return;

        const widget = charlaIcon.shadowRoot.querySelector('.widget');

        if (!widget) return;

        const barHeight = Math.ceil(
            bar.getBoundingClientRect().height
        );

        const targetBottom = barHeight + EXTRA_GAP;

        widget.style.setProperty(
            'bottom',
            targetBottom + 'px',
            'important'
        );

        widget.style.setProperty(
            'top',
            'auto',
            'important'
        );

        widget.style.setProperty(
            'transform',
            'translateX(' + SHIFT_RIGHT + 'px)',
            'important'
        );
    }

    // Charla ładuje się dynamicznie.
    // Czekamy aż utworzy Shadow DOM.
    const init = setInterval(function () {

        moveCharla();

        const charla = document.querySelector('charla-widget');

        if (!charla) return;

        const charlaIcon = charla.querySelector('charla-icon');

        if (!charlaIcon || !charlaIcon.shadowRoot) return;

        const widget =
            charlaIcon.shadowRoot.querySelector('.widget');

        if (!widget) return;

        clearInterval(init);

        // Jeżeli Charla sama zmieni style,
        // natychmiast przywracamy naszą pozycję.
        const observer = new MutationObserver(function () {
            moveCharla();
        });

        observer.observe(widget, {
            attributes: true,
            attributeFilter: ['style']
        });

        // Dodatkowe zabezpieczenie
        // przed wewnętrznym repositioningiem Charli.
        setInterval(moveCharla, 1000);

    }, 250);

    window.addEventListener('resize', moveCharla);
    window.addEventListener('orientationchange', moveCharla);

    if (window.visualViewport) {
        window.visualViewport.addEventListener(
            'resize',
            moveCharla
        );
    }

})();

window.addEventListener('DOMContentLoaded', function() {
    (function($) {

        if (typeof $ === 'undefined') {
            return;
        }

        function hiAnalyzatiAddToCart() {

            if (
                typeof window.pa === 'undefined' ||
                typeof window.pa.track !== 'function'
            ) {
                return;
            }

            window.pa.track({
                name: 'add_to_cart'
            });

            console.log('[Hi DESIGN] Analyzati: add_to_cart');
        }

        /*
         * AJAX Add to Cart
         * WooCommerce loop / archiwum produktów.
         */
        $(document.body).on('added_to_cart', function() {
            hiAnalyzatiAddToCart();
        });

        /*
         * Single product.
         *
         * Zapamiętujemy próbę dodania produktu.
         * Jeżeli formularz jest wysyłany klasycznie,
         * event wykonujemy przy submit.
         */
        $('form.cart').on('submit', function() {

            if ($(this).data('hi-analyzati-sent')) {
                return;
            }

            $(this).data('hi-analyzati-sent', true);

            hiAnalyzatiAddToCart();
        });

    })(window.jQuery);
    });

